// Let's create tabs for the official kit pages
const kitUrls = [
  { name: "23andMe", url: "https://www.23andme.com/dna-health-ancestry/" },
  { name: "Nebula", url: "https://nebula.org/whole-genome-sequencing-dna-test/" },
