  { name: "tellmeGen", url: "https://www.tellmegen.com/en/dna-tests" },
  { name: "Sequencing", url: "https://sequencing.com/dna-test-kits/rare-disease-screen" }
];

const createdTabs = [];
for (const item of kitUrls) {
  const t = await tool.tabs_create({ url: item.url });
  createdTabs.push({ name: item.name, tabId: t.details?.tabId, url: item.url });
  console.log(`Created tab for ${item.name}: ${t.details?.tabId}`);
}

console.log("All kit tabs created:", createdTabs);

